export const MASTER_GARDU_SINJAI_LIST: MasterGarduEntry[] = RAW_MASTER_GARDU_SINJAI.map(
  ([id, penyulang, zonaProteksi, segment, dayaKva, fasa, konstruksi, peruntukan, lat, lng, namaBaru, daerah]) => ({
    id,
    penyulang,
    zonaProteksi,
    segment,
    dayaKva,
    fasa,
    konstruksi,
    peruntukan,
    lat,
    lng,
    namaGardu: namaBaru || `Gardu ${id} (${segment || penyulang})`,
    daerah,
  })
);

const MASTER_GARDU_BY_ID = new Map<string, MasterGarduEntry>(
  MASTER_GARDU_SINJAI_LIST.map((entry) => [entry.id.toUpperCase(), entry])
);

export function findMasterGarduById(garduId: string): MasterGarduEntry | undefined {
  const key = String(garduId || "").trim().toUpperCase();
  if (!key) return undefined;
  return (
    MASTER_GARDU_BY_ID.get(key) ||
    MASTER_GARDU_SINJAI_LIST.find(
      (g) => g.id.toUpperCase() === key || key.includes(g.id.toUpperCase())
    )
  );
}
